Here is the commit message:
crypto: cavium/nitrox - Use after free in
 process_response_list()

We free "sr" and then dereference it on the next line.

Fixes: c9613335bf4f ("crypto: cavium/nitrox - Added AEAD cipher support")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug is caused by the premature freeing of the `sr` pointer before it is dereferenced to read the error code. This leads to a use-after-free condition, where the code attempts to access memory that has already been released, potentially resulting in undefined behavior or crashes.

Here is the patch:
  */
 static void process_response_list(struct nitrox_cmdq *cmdq)
 {
 	struct nitrox_device *ndev = cmdq->ndev;
 	struct nitrox_softreq *sr;
 	int req_completed = 0, err = 0, budget;

 	/* check all pending requests */
 	budget = atomic_read(&cmdq->pending_count);

 	while (req_completed < budget) {
 		sr = get_first_response_entry(cmdq);
 		if (!sr)
 			break;

 		if (atomic_read(&sr->status) != REQ_POSTED)
 			break;

 		/* check orh and completion bytes updates */
 		if (!sr_completed(sr)) {
 			/* request not completed, check for timeout */
 			if (!cmd_timeout(sr->tstamp, ndev->timeout))
 				break;
 			dev_err_ratelimited(DEV(ndev),
 					    "Request timeout, orh 0x%016llx\n",
 					    READ_ONCE(*sr->resp.orh));
 		}
 		atomic_dec(&cmdq->pending_count);
 		atomic64_inc(&ndev->stats.completed);
 		/* sync with other cpus */
 		smp_mb__after_atomic();
 		/* remove from response list */
 		response_list_del(sr, cmdq);

 		/* ORH error code */
 		err = READ_ONCE(*sr->resp.orh) & 0xff;
-		softreq_destroy(sr);

 		if (sr->callback)
 			sr->callback(sr->cb_arg, err);
+		softreq_destroy(sr);

 		req_completed++;
 	}
 }



